SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
START TRANSACTION;
INSERT INTO promotion_diy_template (name,used,used_time,remark,preview_pic_urls,property,tenant_id) SELECT CONVERT(0xe69cace59cb0e5bc80e58f91e59586e59f8e USING utf8mb4) COLLATE utf8mb4_unicode_ci,1,NOW(),CONVERT(0xe69cace59cb0e5bc80e58f91e5889de5a78be58c96e6a8a1e69dbfefbc8ce58fafe59ca8e5908ee58fb0e8a385e4bfae USING utf8mb4) COLLATE utf8mb4_unicode_ci,'[]',CONVERT( USING utf8mb4) COLLATE utf8mb4_unicode_ci,1 WHERE NOT EXISTS (SELECT 1 FROM promotion_diy_template WHERE tenant_id=1 AND used=1 AND deleted=0);
SET @template_id=(SELECT id FROM promotion_diy_template WHERE tenant_id=1 AND used=1 AND deleted=0 LIMIT 1);
INSERT INTO promotion_diy_page (template_id,name,remark,preview_pic_urls,property,tenant_id) SELECT @template_id,CONVERT(0xe9a696e9a1b5 USING utf8mb4) COLLATE utf8mb4_unicode_ci,'local development','[]',CONVERT( USING utf8mb4) COLLATE utf8mb4_unicode_ci,1 WHERE @template_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM promotion_diy_page WHERE template_id=@template_id AND name=CONVERT(0xe9a696e9a1b5 USING utf8mb4) COLLATE utf8mb4_unicode_ci AND deleted=0);
INSERT INTO promotion_diy_page (template_id,name,remark,preview_pic_urls,property,tenant_id) SELECT @template_id,CONVERT(0xe68891e79a84 USING utf8mb4) COLLATE utf8mb4_unicode_ci,'local development','[]',CONVERT( USING utf8mb4) COLLATE utf8mb4_unicode_ci,1 WHERE @template_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM promotion_diy_page WHERE template_id=@template_id AND name=CONVERT(0xe68891e79a84 USING utf8mb4) COLLATE utf8mb4_unicode_ci AND deleted=0);
COMMIT;
